/* Explicitly synthetic, isolated baby; deterministic 14-day UI preview. */
const DemoData={id:'baby-demo-14d',build(now=new Date()){const records=[],local=d=>new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);let n=0;for(let offset=13;offset>=0;offset--){const day=new Date(now);day.setDate(day.getDate()-offset);const at=(h,m=0)=>{const d=new Date(day);d.setHours(h,m,0,0);return d};const add=(type,h,m,data)=>{const d=at(h,m);if(d>now)return;records.push({id:'demo14-'+local(d)+'-'+type,babyId:this.id,type,owner:type==='吸奶'?'妈妈':'宝宝',time:local(d),source:'demo',...data})};[6,9,12,15,18,21].forEach((h,i)=>add(i%3===0?'瓶喂母乳':'配方奶',h,10+(offset%3)*5,{amount:90+((offset+i)%5)*15}));[[7,20],[10,40],[14,10],[17,30],[20,20]].forEach(([h,m],i)=>add('换尿布',h,m,{kind:i===2?'都有':i===4?'便便':'尿尿'}));[[6,0,360],[11,40,75],[15,0,90],[18,0,35]].forEach(([h,m,d])=>add('睡眠',h,m,{duration:d+(offset%3)*5}));add('亲喂',4,30,{duration:15+(offset%4)*3,side:offset%2?'左侧':'右侧'});add('吸奶',8,30,{amount:100+(offset%4)*10});if(offset%2===0)add('体重',8,0,{weight:Number((6.1+(13-offset)*.018+(offset%3)*.015).toFixed(2))});if(offset%3===0)add('辅食',13,0,{note:'南瓜泥 · 少量尝试（示例）'});}const birth=new Date(now);birth.setMonth(birth.getMonth()-6);return {baby:{id:this.id,name:'小禾 · 示例',kind:'born',gender:'female',birth:local(birth).slice(0,10),isDemo:true},records}}};
